"OLAYLAR_GEZGINLER:1885-06-30:0":{"b": ["Tyumen – Ishim – Omsk – Pavlodar – Semipalatinsk (Kennan, jalan pos)", "38cf5734"], "d": ["Rute: Tyumen → Ishim → Omsk → Pavlodar → Semipalatinsk. Seluruh perjalanan ditampilkan di peta sebagai garis perjalanan.", "6e173245"]},
"OLAYLAR_GEZGINLER:1885-08-28:0":{"b": ["Tomsk – Achinsk – Krasnoyarsk (Kennan, Jalan Besar Siberia)", "11af8d7b"], "d": ["Rute: Tomsk → Achinsk → Krasnoyarsk. Seluruh perjalanan ditampilkan di peta sebagai garis perjalanan.", "2dbebae4"]},
"OLAYLAR_GEZGINLER:1885-09-24:0":{"b": ["Irkutsk – Listvyanka (Baikal) – Selenginsk – Verkhneudinsk – Chita (Kennan)", "c0a18681"], "d": ["Rute: Irkutsk → Listvyanka → Selenginsk → Verkhneudinsk → Chita. Seluruh perjalanan ditampilkan di peta sebagai garis perjalanan.", "498cf501"]},
